-- 던클리 실제 익명 ID 패턴 기반 total 반영용 SQL
-- 기존 synthetic_mix_382 / syn_total_382_% / 실제 ID 패턴 파생 mix 데이터 정리 후 재삽입
-- 실행 전 백업 권장:
-- sqlite3 /var/data/data.sqlite ".backup '/var/data/data_before_real_id_pattern_382.sqlite'"
